"""Use a basic dark editorial shell with six navigation links."""
from pathlib import Path
import re,html,hashlib
R=Path(__file__).resolve().parents[1];E=html.escape
MENU=[('index.html','The story'),('history/','Timeline'),('state-files/','States'),('forms/','Forms & law'),('evidence/','Documents'),('methodology/','SIR basics')]
for p in R.rglob('*.html'):
 t=p.read_text()
 if 'data-redirect="true"' in t:continue
 if p.name=='404.html':
  p.write_text('<!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Page not found | The SIR Files</title><link rel="stylesheet" href="/the-sir-files/assets/site.css"></head><body><main class="container"><h1>Page not found.</h1><p><a href="/the-sir-files/">Read the SIR story →</a></p></main></body></html>');continue
 relative=p.relative_to(R).as_posix();depth=len(p.relative_to(R).parts)-1;base='../'*depth
 title=html.unescape(re.search(r'<title>(.*?)</title>',t,re.S)[1]);desc=re.search(r'<meta name="description" content="([^"]*)',t);desc=html.unescape(desc[1]) if desc else ''
 if relative=='state-files/tripura/index.html':desc='Tripura’s original schedule and later reported timetable describe different stages. The signed replacement order remains unverified.'
 main=re.search(r'<main .*?</main>',t,re.S)[0]
 main=re.sub(r'<div class="reading-tools">.*?</div>','',main,flags=re.S)
 main=re.sub(r'<details class="page-contents">.*?</details>','',main,flags=re.S)
 main=re.sub(r'<section class="case-context".*?</section>','',main,flags=re.S)
 main=re.sub(r'<nav class="chapter-continue".*?</nav>','',main,flags=re.S)
 main=re.sub(r'<aside class="sticky-aside">.*?</aside>','',main,flags=re.S)
 for old,new in [('Sources and qualifications','Documents'),('Evidence still needed','What is still unknown'),('What is established here','What happened'),('STATE FILE / DETAILED FILE','STATE REPORT'),('STATE FILE / REFERENCE FILE','STATE NOTE'),('This publication has completed no independent person-level legality audit in this jurisdiction. A developed article or reference file is not a completed forensic investigation.','The published records do not establish whether every individual decision was correct.')]:main=main.replace(old,new)
 for old,new in [('FULL RESEARCH AUDIT / 17 OCT 2026','EXPLAINER / 17 OCTOBER 2026'),('RESEARCH NOTE / 17 OCTOBER 2026','EXPLAINER / 17 OCTOBER 2026'),('CLAIMS / FULL AUDIT','STATEMENTS CHECKED'),('GAP REGISTER / 17 OCT 2026','UNANSWERED QUESTIONS'),('EVIDENCE / SOURCE AUDIT','DOCUMENTS'),('The claims register.','Statements checked.'),('Each claim has a source, a limit and the next evidence needed.','Read the source and its limits for each statement.'),('A source gap and an outcome gap are different. This register records both.','Some documents are missing. Other records are available but do not show what happened to individual voters.'),('Keep four artefacts distinct','Four different records'),('Artefact','Record'),('What a reproducible comparison needs','Which version was used?')]:main=main.replace(old,new)
 if relative=='state-files/tripura/index.html':
  main=main.replace('A past version of our own investigation misread Tripura’s claims deadline. The signed ECI annexure resolves the matter.','Tripura’s original schedule and later reported timetable describe different stages. The signed replacement order remains unverified.')
  main=main.replace('The earlier misreading of the original May claims window remains corrected.','The original May order gives a claims window from 21 October to 20 November.')
  main=main.replace('Why the correction stays public','The original claims window').replace('A research archive should preserve its corrections. The evidence label was changed when the original document was examined, rather than concealing the old error.','The signed original annexure sets 21 October to 20 November. Later reported dates require the replacement order to establish which schedule applies.')
 main=main.replace('<p>No records requests, court filings or institutional communications have been sent by this publication.</p>','')
 if relative=='evidence/index.html':
  main=main.replace('Inspect the record.','Original documents.').replace('Source records include aliases, mirrors and one unverified retrieval lead. Counts are not counts of independent corroborating documents.','Orders, judgments and official figures. Search by state or topic. Each entry explains what the document supports and its limits. Some entries refer to copies or links that remain unverified.')
 nav=''.join(f'<a href="{base}{path}"'+(' aria-current="page"' if relative==path or relative==path+'index.html' else '')+'>'+E(label)+'</a>' for path,label in MENU)
 css=hashlib.sha256((R/'assets/site.css').read_bytes()).hexdigest()[:12];js=hashlib.sha256((R/'assets/site.js').read_bytes()).hexdigest()[:12];idx=hashlib.sha256((R/'assets/search-data.js').read_bytes()).hexdigest()[:12]
 p.write_text(f'''<!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>{E(title)}</title><meta name="description" content="{E(desc,quote=True)}"><link rel="stylesheet" href="{base}assets/site.css?v={css}"><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"></head><body data-base="{base}"><a class="skip" href="#main">Skip to article</a><header class="site-header"><div class="masthead"><a class="wordmark" href="{base}index.html">THE SIR FILES<span>.</span></a><div class="header-actions"><button data-search-open aria-label="Search all articles">Search</button><button class="menu-trigger" data-menu-open aria-label="Open menu" aria-expanded="false" aria-controls="menu-panel"><span class="hamburger" aria-hidden="true"><i></i><i></i><i></i></span><span class="menu-label">Menu</span></button></div></div></header><div id="menu-panel" class="menu-panel" role="dialog" aria-modal="true" aria-label="Site menu" hidden><button class="menu-backdrop" data-menu-close tabindex="-1" aria-label="Close menu"></button><aside class="menu-drawer"><div class="menu-heading"><span>THE SIR FILES</span><button id="menu-close" data-menu-close aria-label="Close menu">✕</button></div><nav class="main-menu" aria-label="Main menu">{nav}</nav><p class="menu-note">Special Intensive Revision, explained in date order.</p></aside></div>{main}<footer class="footer"><span>THE SIR FILES · Events covered through 17 October 2026</span><a href="{base}methodology/">What the SIR figures mean</a></footer><div id="search-modal" class="search-modal" role="dialog" aria-label="Search The SIR Files" aria-modal="true"><div class="search-box"><div class="search-row"><input id="site-search" type="search" aria-label="Search articles" placeholder="Search a state, date or topic…"><button data-search-close>Close</button></div><div id="search-results" class="search-results"></div></div></div><script src="{base}assets/search-data.js?v={idx}"></script><script src="{base}assets/site.js?v={js}"></script></body></html>''')
print('Applied dark theme and six-item menu')
